effect.shader:
/** Luminância ITU-R BT.709. */
float luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

/** Matriz de Bayer 4×4 (valores 0..15 / 16): o dithering ordenado clássico. */
const float BAYER[16] = float[16](
     0.0 / 16.0,  8.0 / 16.0,  2.0 / 16.0, 10.0 / 16.0,
    12.0 / 16.0,  4.0 / 16.0, 14.0 / 16.0,  6.0 / 16.0,
     3.0 / 16.0, 11.0 / 16.0,  1.0 / 16.0,  9.0 / 16.0,
    15.0 / 16.0,  7.0 / 16.0, 13.0 / 16.0,  5.0 / 16.0
);

float bayerEm(ivec2 p) {
    int x = p.x - (p.x / 4) * 4;
    int y = p.y - (p.y / 4) * 4;
    return BAYER[y * 4 + x];
}

void main() {
    vec2 tam = vec2(textureSize(inputImg, 0));
    float lado = max(cellSize, 1.0);

    // 1. Rasteriza em pixels grandes.
    vec2 pixelado = floor(acScreenNorm * tam / lado) * lado / tam + (lado * 0.5) / tam;
    vec4 original = texture(inputImg, pixelado);

    // 2. Satura antes de quantizar (pra puxar as cores ao perfil retrô).
    vec3 cinza = vec3(luma(original.rgb));
    vec3 saturada = mix(cinza, original.rgb, saturation);

    // 3. Dithering ordenado + quantização.
    int n = clamp(int(levels + 0.5), 2, 8);
    float passo = 1.0 / float(n - 1);
    ivec2 p = ivec2(acScreenNorm * tam / lado);
    float d = (bayerEm(p) - 0.5) * passo * dither;

    vec3 quantizada = clamp(saturada + vec3(d), 0.0, 1.0);
    quantizada = floor(quantizada * float(n - 1) + 0.5) / float(n - 1);

    fragColor = vec4(quantizada, original.a);
}
